function observeReveals(){const els=document.querySelectorAll('.reveal:not(.revealed)');if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('revealed'));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');io.unobserve(e.target)}}),{threshold:.08});els.forEach(e=>io.observe(e));}
